// MIT. K125 own native body plus own-photo inferred complete physical inserts.
import {Port,Led} from '../../core/index.js';
import {THREE,materials,FACE,portQuaternion,mesh,box,plate,cylinder,annulus,ownNative} from './geometry.js';
import native from './native-data.js';
import {nativeInputs} from './NativeInputs.js';
import {DIM,spec} from './dimensions.js';
const mark=(o,family)=>{o.userData.visualFamily=family;return o;};
function group(h,name,p=[0,0,0],face){const g=new THREE.Group();g.name=name;g.position.fromArray(p);if(face)g.quaternion.copy(FACE[face]);h.body.add(g);return g;}
export function buildAssembly(host){const a={parts:ownNative(host,native)};host.atomS3UAssembly=a;const dark=materials.plastic(0x15201b,{roughness:.8}),white=materials.plastic(0xe7e9e1,{roughness:.65}),board=materials.plastic(0x204a39,{roughness:.86}),metal=materials.metal(0xb9beb7,{roughness:.35}),gold=materials.metal(0xc2b07b,{roughness:.39});
 a.pcb=plate(host.body,14.8,33,.8,[0,6.2,-.65],board,'K125 actual thick ESP32-S3FN8 main PCB',{radius:.7,holes:[{radius:.3,x:-6.4,y:-14},{radius:.3,x:6.4,y:-14},{radius:.3,x:-6.4,y:14},{radius:.3,x:6.4,y:14}]});
 for(const [x,y]of [[-6.4,-7.8],[6.4,-7.8],[-6.4,20.2],[6.4,20.2]]){annulus(host.body,.55,.29,2.45,[x,y,-3.1],white,'K125 physical main PCB supporting standoff');cylinder(host.body,.27,.18,[x,y,.25],metal,'K125 PCB physical retaining fastener');}
 box(host.body,[7,7,.9],[0,6,.6],dark,'K125 ESP32-S3FN8 actual package inferred envelope');box(host.body,[3.5,2.2,1.3],[4,15,.8],white,'K125 real 3D antenna inferred placement');for(const [x,y]of [[-5,5],[-5,8],[4,3],[5,10],[0,16]]){box(host.body,[1.3,.85,.6],[x,y,.45],materials.plastic(0xa69e7f,{roughness:.84}),'K125 actual passive envelope');for(const dx of [-.7,.7])box(host.body,[.2,.85,.14],[x+dx,y,.23],metal,'K125 passive solder terminal');}
 // Real USB-A male plug:four thick metal walls,two top latching bores,dielectric tongue and four exposed contacts.
 const plug=group(host,'K125 complete physical USB-A male plug');a.usb=plug;
 plate(plug,12,12.8,.30,[0,-20.1,2.35],metal,'K125 USB-A thick top wall with two real latching holes',{radius:.04,holes:[{w:1.75,h:2.2,r:.04,x:-3,y:-1.2},{w:1.75,h:2.2,r:.04,x:3,y:-1.2}]});box(plug,[12,12.8,.3],[0,-20.1,-1.60],metal,'K125 USB-A thick bottom wall');for(const x of [-5.85,5.85])box(plug,[.3,12.8,3.95],[x,-20.1,.375],metal,'K125 USB-A thick side wall');
 box(plug,[10.6,2.0,3.3],[0,-13.25,.55],dark,'K125 USB-A actual rear dielectric package neck');a.usbTongue=box(plug,[10.8,12.5,1.6],[0,-20.25,-.55],dark,'K125 USB-A actual dielectric male contact tongue');for(let i=0;i<4;i++){const c=mark(box(plug,[1.05,7,.12],[(i-1.5)*2.5,-22,.31],gold,'K125 USB-A actual signal contact '+(i+1)),'usb-a-contact');c.userData.pin=i+1;box(host.body,[.45,4,.2],[(i-1.5)*2.5,-12,.1],gold,'K125 USB-A PCB contact tail '+(i+1));}
 host.add(new Port({id:'usb',label:'K125 USB-A male power/program',connector:'usb-a',position:DIM.usb,quaternion:portQuaternion('bottom'),hitSize:[12,1,4.4],pins:['5V','D-','D+','GND'].map((name,i)=>({n:i+1,name,signal:name})),meta:{face:'bottom',gender:'male',role:'visual-connector',scope:'Actual plug geometry/frame only;no USB or power protocol'}}));
 const grove=group(host,'K125 complete HY2.0-4P receiver',DIM.grove,'top');a.grove=grove;mark(plate(grove,10.1,3.6,6.25,[0,0,-6.25],white,'K125 Grove keyed thick molded receiver',{radius:.22,holes:[{w:8.7,h:3.3,r:.15}]}),'grove-receiver');mark(box(grove,[8.68,3.29,.5],[0,0,-6],white,'K125 Grove actual dielectric deep rear wall'),'grove-rear-wall');for(const x of [-4.4,4.4])box(grove,[.65,.58,1.3],[x,1.55,-.5],white,'K125 Grove physical latch rail');for(let i=0;i<4;i++){const c=mark(box(grove,[.4,.4,4.7],[(i-1.5)*2,-.2,-3.4],gold,'K125 Grove actual contact '+(i+1)),'grove-contact');c.userData.pin=i+1;box(grove,[.4,.4,1.1],[(i-1.5)*2,-.2,-6.55],gold,'K125 Grove contact rear tail');}host.add(new Port({id:'grove',label:'K125 Grove · GND/5V/G2/G1',connector:'grove',position:DIM.grove,quaternion:portQuaternion('top'),hitSize:[10.8,1,4.5],pins:spec.grovePins.map((name,i)=>({n:i+1,name,signal:name})),meta:{face:'top',role:'visual-connector',scope:'Four-wire mechanical connection only;no bus/power emulation'}}));
 const header=group(host,'K125 true six-pin female extension',DIM.header,'top');a.header=header;const holes=Array.from({length:6},(_,i)=>({w:1.02,h:1.02,r:.05,x:(i-2.5)*2.54}));mark(plate(header,15.1,1.8,2.3,[0,0,-2.3],dark,'K125 six-pin thick molded bored receiver',{radius:.04,holes}),'female-header-housing');for(let i=0;i<6;i++){const x=(i-2.5)*2.54;mark(box(header,[1.02,1.02,.12],[x,0,-2.24],dark,'K125 six-pin true deep floor '+(i+1)),'header-socket-floor');for(const sign of [-1,1])mark(box(header,[.66,.12,1.28],[x,sign*.34,-1.12],gold,'K125 six-pin actual spring contact '+(i+1)),'header-spring-contact');box(host.body,[.25,3,.25],[x,22.4,-2.6],gold,'K125 six-pin real PCB tail');}host.add(new Port({id:'ext-6p',label:'K125 six-pin female expansion',connector:'m5.atom.ext-6p',position:DIM.header,quaternion:portQuaternion('top'),hitSize:[15.1,1,2.2],pins:spec.headerPins.map((name,i)=>({n:i+1,name,signal:name})),pinGrid:{cols:6,rows:1,pitch:2.54,center:[0,0]},meta:{face:'top',gender:'female',role:'visual-connector',scope:'Labels and mechanical frame only;no GPIO/power behavior'}}));
 const main=group(host,'K125 G41 actual PCB tactile switch');a.mainSwitch=plate(main,3.5,3.5,1.25,[0,0,.4],dark,'K125 G41 thick real bored switch housing',{radius:.14,holes:[{radius:.48}]});a.mainPlunger=cylinder(main,.46,1.1,[0,0,2.0],white,'K125 G41 fixed physical actuator');
 const reset=group(host,'K125 independent Reset switch housing',[-7.45,11.3,-.5],'left');plate(reset,3.2,2.2,1.0,[0,0,-1],dark,'K125 Reset thick real bored switch housing',{radius:.14,holes:[{radius:.55}]});a.resetPlunger=cylinder(host.body,.52,.3,[-8.24,11.3,-.5],white,'K125 actual Reset moving physical head','x');
 // Microphone and RGB are independent physical packages behind the real slit.
 a.microphone=plate(host.body,1.8,1.3,.65,[1.0,-1.5,2.3],metal,'K125 real SPM1423 microphone package with acoustic bore',{radius:.05,holes:[{radius:.18}]});a.micStop=cylinder(host.body,.18,.15,[1.0,-1.5,2.05],dark,'K125 microphone actual recessed acoustic substrate');a.rgbPackage=box(host.body,[1.8,1.3,.7],[-1,-1.5,2.2],white,'K125 actual WS2812 RGB package');const lens=box(host.body,[1.5,.29,.25],[-.9,-1.5,3.3],materials.plastic(0xdce4d8,{roughness:.45}),'K125 RGB actual optical diffuser behind native slit');a.rgb=host.add(new Led({id:'rgb',label:'K125 WS2812 RGB · G35',mesh:lens,radius:0,glowSize:2.5,meta:{gpio:'G35',role:'externally-driven-visual',scope:'Visible light only;no boot or microphone behavior'}}));a.rgb.glow.position.set(-.9,-1.5,5.22);
 a.ir=cylinder(host.body,.3,1.0,[-7.6,25.45,3.8],dark,'K125 G12 passive IR physical resin body','y');a.irLens=mesh(host.body,new THREE.SphereGeometry(.3,24,16),materials.glossy(0x1b2820,{roughness:.28}),[-7.6,25.95,3.8],'K125 passive IR real optical dome');a.irLens.scale.y=.7;for(const x of [-7.8,-7.4])box(host.body,[.12,.8,.15],[x,24.8,3.6],gold,'K125 IR physical metal lead');
 nativeInputs(host,a.parts['control-shell'],a);return a;
}
